insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pay-online-with-a-card', 'Can I pay online with a card?', '<p>Yes — when Stripe checkout is enabled, pay securely from <a href="/account/transactions">property applications</a>. Otherwise bank transfer with manual confirmation.</p>', 'Can I pay online with a card?', 92, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-my-online-payment-secure', 'Is my online payment secure?', '<p>Card payments process via Stripe; we never store full card numbers. See <a href="/pages/privacy">Privacy Policy</a> for data handling.</p>', 'Is my online payment secure?', 93, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-currency-are-payments-in', 'What currency are payments in?', '<p>AED (UAE Dirham) for Dubai properties. Display follows site currency settings on listings.</p>', 'What currency are payments in?', 94, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-is-the-invoice-generated', 'When is the invoice generated?', '<p>After agent builds payment breakdown — you or your agent creates invoice in <a href="/account/transactions">property applications</a>.</p>', 'When is the invoice generated?', 95, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pay-in-instalments-for-a-sale', 'Can I pay in instalments for a sale?', '<p>Off-plan follows developer payment plans; ready sales usually require staged payments per SPA. Details in <a href="/pages/buying-guide">Buying Guide</a> and <a href="/account/transactions">property applications</a>.</p>', 'Can I pay in instalments for a sale?', 96, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-if-my-payment-fails-online', 'What if my payment fails online?', '<p>Retry from <a href="/account/transactions">property applications</a> or <a href="/pages/contact">contact our team</a> for bank transfer instructions. Invoice stays pending until paid.</p>', 'What if my payment fails online?', 97, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-refunds-available-after-payment', 'Are refunds available after payment?', '<p>Refund rules depend on contract stage and owner policy. Deposits may be non-refundable after MOU/SPA — review <a href="/pages/terms">Terms of Service</a>.</p>', 'Are refunds available after payment?', 98, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'who-receives-my-payment', 'Who receives my payment?', '<p>Agency fees to GW Vacation Homes; rent/sale funds per contract (owner/developer/escrow). Breakdown clarifies each line in <a href="/account/transactions">property applications</a>.</p>', 'Who receives my payment?', 99, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-get-a-receipt-after-payment', 'Do I get a receipt after payment?', '<p>Yes — invoice marked paid in <a href="/account/transactions">property applications</a> with confirmation notification. Email receipt when Stripe is used.</p>', 'Do I get a receipt after payment?', 100, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-the-agency-commission-on-rent', 'What is the agency commission on rent?', '<p>Typically 5% of annual rent + VAT. Shown in breakdown before you pay — browse <a href="/collection/rentals">holiday and long-term rentals</a> with confidence.</p>', 'What is the agency commission on rent?', 101, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-the-agency-commission-on-sales', 'What is the agency commission on sales?', '<p>Typically 2% of sale price + VAT unless otherwise agreed. Disclosed in <a href="/account/transactions">property applications</a>.</p>', 'What is the agency commission on sales?', 102, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-admin-fees-mandatory', 'Are admin fees mandatory?', '<p>Admin/Ejari fees cover registration and processing — itemised in breakdown. See <a href="/pages/renting-guide">Renting Guide</a> for typical ranges.</p>', 'Are admin fees mandatory?', 103, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pay-from-outside-the-uae', 'Can I pay from outside the UAE?', '<p>International wire accepted for many transactions. <a href="/pages/contact">contact our team</a> for SWIFT details and currency conversion notes.</p>', 'Can I pay from outside the UAE?', 104, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'when-is-the-security-deposit-due', 'When is the security deposit due?', '<p>Usually at contract signing with first rent cheque. Timeline in <a href="/account/transactions">property applications</a> payment schedule.</p>', 'When is the security deposit due?', 105, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'does-vat-apply-to-agency-fees', 'Does VAT apply to agency fees?', '<p>Yes — 5% UAE VAT on taxable agency services. Included in breakdown total in <a href="/account/transactions">property applications</a>.</p>', 'Does VAT apply to agency fees?', 106, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-confirm-a-bank-transfer-payment', 'How do I confirm a bank transfer payment?', '<p>Upload proof or click Confirm Payment in <a href="/account/transactions">property applications</a> if quote mode is enabled. Agent verifies and updates status.</p>', 'How do I confirm a bank transfer payment?', 107, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-payment-methods-are-accepted', 'What payment methods are accepted?', '<p>Visa, Mastercard, Amex (via Stripe where enabled), bank transfer, and post-dated cheques for rent per contract.</p>', 'What payment methods are accepted?', 108, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-do-i-see-payment-history', 'Where do I see payment history?', '<p>Inside each transaction in <a href="/account/transactions">property applications</a> — invoices and payment status per property.</p>', 'Where do I see payment history?', 109, true from public.faq_categories where slug = 'payments-fees' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-register-ejari-for-my-tenancy', 'How do I register Ejari for my tenancy?', '<p>We coordinate Ejari after contract signing and initial payment. Required documents listed in <a href="/pages/shipping">Handover Information</a> and <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'How do I register Ejari for my tenancy?', 110, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-much-does-ejari-registration-cost', 'How much does Ejari registration cost?', '<p>Ejari fees are approximately AED 220 including VAT — included in your <a href="/account/transactions">property applications</a> breakdown when applicable.</p>', 'How much does Ejari registration cost?', 111, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-connect-dewa-electricity-and-water', 'How do I connect DEWA electricity and water?', '<p>Apply online at DEWA with Ejari, ID, and deposit (typically AED 2,130 for apartments). We guide you at handover — <a href="/pages/shipping">Handover Information</a>.</p>', 'How do I connect DEWA electricity and water?', 112, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-dewa-security-deposit', 'What is a DEWA security deposit?', '<p>Refundable deposit held by DEWA — AED 2,000 apartments / AED 4,000 villas (approx.). Refunded minus final bill on move-out.</p>', 'What is a DEWA security deposit?', 113, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-does-dewa-activation-take', 'How long does DEWA activation take?', '<p>Usually 1–24 hours after application with valid Ejari. Plan activation for handover day in <a href="/account/transactions">property applications</a>.</p>', 'How long does DEWA activation take?', 114, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-district-cooling-vs-dewa', 'What is district cooling vs DEWA?', '<p>DEWA covers electricity and water; district cooling (Empower) is separate chilled water AC billing. Confirm payer in lease via <a href="/account/transactions">property applications</a>.</p>', 'What is district cooling vs DEWA?', 115, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-the-previous-tenant-dewa-account-be-transferred', 'Can the previous tenant DEWA account be transferred?', '<p>Final bill must close old account before new registration. Coordinate move-in/out dates with agent via <a href="/pages/contact">contact our team</a>.</p>', 'Can the previous tenant DEWA account be transferred?', 116, true from public.faq_categories where slug = 'ejari-dewa-utilities' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
